package com.energie.platform.config;
import io.swagger.v3.oas.models.*; import io.swagger.v3.oas.models.info.Info; import io.swagger.v3.oas.models.security.*; import org.springframework.context.annotation.*;
@Configuration public class OpenApiConfig {@Bean OpenAPI energieOpenApi(){return new OpenAPI().info(new Info().title("Energie Platform API").version("1.0.0").description("Backend de génération de demandes pour rénovation énergétique belge." )).addSecurityItem(new SecurityRequirement().addList("bearerAuth")).components(new Components().addSecuritySchemes("bearerAuth",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT")).addSecuritySchemes("aiApiKey",new SecurityScheme().type(SecurityScheme.Type.APIKEY).in(SecurityScheme.In.HEADER).name("X-API-KEY")));}}
